"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1058-02-28:0":{"b": ["Abadidi su od Hamudida preuzeli Algeciras (Džeziretul-Hadru) (450/1058)", "a2ac7bdd"], "d": ["Kasimov sin Muhammed el-Mehdi i unuk Kasim el-Vasik upravljali su Algecirasom dok ga nisu zauzeli Abadidi (seviljska tajfa) (450/1058); tako je prestala hamudidska vlast u Algecirasu.", "5c22a7ca"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1061-01-26:0":{"b": ["Uprava nad oblašću Fesa prepuštena je Jusufu b. Tašfinu (453, 1061).", "6c0af3bc"], "d": ["Uprava nad oblašću Fesa prepuštena je Jusufu b. Tašfinu (453, 1061).", "6c0af3bc"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1062-01-15:0":{"b": ["Ebu Bekr b. Omer počeo je graditi grad Marakeš (454, 1062).", "1312fb2d"], "d": ["Ebu Bekr b. Omer počeo je graditi grad Marakeš (454, 1062).", "1312fb2d"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1065-11-10:0":{"b": ["Zunnunid Jahja el-Mamun zbacio je Amirida Abdulmelika; Balansija (Valensija) prešla je Zunnunidima", "3bb5a927"], "d": ["Vladar Toleda (Tulajtule), Zunnunid Jahja el-Mamun, zbacio je amiridskog vladara Abdulmelika s prijestolja (8. zul-hidždže 457 / 10. novembar 1065); Zunnunidi su od 457. do 462. (1065–1070) vladali Šatibom i Balansijom (Valensijom), koje su bile u rukama Amirida.", "aad35ff8"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1070-01-01:0":{"b": ["Kordoba je nakon Džehverida prešla Abadidima", "fc156474"], "d": ["Džehveridska uprava trajala je do 1070; potom je Kordoba pala u ruke abadidskog emirata sa središtem u Sevilji.", "d8bc19d6"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1080-01-01:0":{"b": ["Almoravidi su zauzeli Tlemsen, Udždu i Oran i stigli do grada Alžira", "cefef422"], "d": ["Jusuf b. Tašfin okrenuo se prema Srednjem Magrebu, zauzeo Udždu, Tlemsen i Oran i stigao sve do grada Alžira (1080); u Alžiru je dao sagraditi el-Džamiu'l-kebir.", "8bfdcd25"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1085-05-08:0":{"b": ["Toledo je predat Kastilji; Zunnunid Jahja el-Kadir povukao se u Balansiju", "e0a87ca9"], "d": ["Na kraju opsade koja je trajala oko devet mjeseci Toledo (Tulajtula) mirnim je putem predat Kraljevini Kastilji Alfonsa VI (8. maj 1085); zunnunidski vladar Jahja el-Kadir s porodicom i pratnjom otišao je u Balansiju (Valensiju) i ondje vladao. U atlasu Valensija od tog dana izlazi iz oznake Zunnunidi (toledska tajfa) i prelazi u zapis Muluku't-tavaif (andaluzijski tajfa emirati).", "a494fcd4"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1086-06-30:0":{"b": ["Jusuf b. Tašfin iskrcao se u Algecirasu; prvi prelazak u Andaluziju", "ad79ab8b"], "d": ["Na poziv trinaest andaluzijskih emira, Jusuf se pod uslovom da mu se preda Algeciras 15. rebiul-evvela 479 (30. juni 1086) iskrcao na obalu i prešao u Sevilju.", "77396cfd"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1086-10-23:0":{"b": ["Jusuf b. Tašfin porazio je kastiljsku vojsku kod Zalake (12. redžeb 479).", "7f7d340d"], "d": ["Jusuf b. Tašfin porazio je kastiljsku vojsku kod Zalake (12. redžeb 479).", "7f7d340d"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1087-04-08:0":{"b": ["Umro je Ebu Bekr b. Omer (480, 1087).", "00e73559"], "d": ["Umro je Ebu Bekr b. Omer (480, 1087).", "00e73559"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1094-06-15:0":{"b": ["El Cid je zauzeo Valensiju: osnovana je Valensijska (El Cidova) kneževina", "f5b81beb"], "d": ["Rodrigo Díaz de Vivar (El Cid) nakon opsade je 15. juna 1094. preuzeo kontrolu nad Valensijom (Balansijom); na položaju kadije ostavio je Ibn Džehhafa. Valensija je izašla iz zapisa Muluku't-tavaif (andaluzijski tajfa emirati) i prešla u Valensijsku (El Cidovu) kneževinu.", "e51445ac"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1102-01-01:0":{"b": ["Almoravidi su zauzeli Balansiju", "ce05cefc"], "d": ["Balansiju, koja je nakon Rodrigove smrti 1099. bila u rukama njegove supruge Ximene, Almoravidi su zauzeli 1102.", "8407a408"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1102-05-05:0":{"b": ["Almoravidi su zauzeli Balansiju (Valensiju) (1102)", "833a9c9a"], "d": ["Nakon El Cidove smrti 1099. grad je ostao njegovoj udovici Jimeni; Balansiju su 1102. zauzeli Almoravidi. Valensija tada izlazi iz Valensijske (El Cidove) kneževine i prelazi Državi Almoravida.", "a9ecdc4d"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1106-09-04:0":{"b": ["Jusuf b. Tašfin umro je u Marakešu; naslijedio ga je sin Ali b. Jusuf", "3a60ecd3"], "d": ["Jusuf b. Tašfin umro je u Marakešu; naslijedio ga je sin Ali b. Jusuf", "3a60ecd3"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1108-01-01:0":{"b": ["Ali b. Jusuf izvojevao je kod Uclésa pobjedu nad kršćanskom vojskom (501, 1108).", "8380cd9c"], "d": ["Ali b. Jusuf izvojevao je kod Uclésa pobjedu nad kršćanskom vojskom (501, 1108).", "8380cd9c"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1110-01-24:0":{"b": ["Umro je hudidski emir Ahmed el-Mustain; almoravidska vojska krenula je na Zaragozu", "8378eeaf"], "d": ["Nakon smrti Ahmeda el-Mustaina-Billaha (1. redžeb 503 / 24. januar 1110) jedna almoravidska vojska krenula je iz Balansije prema Zaragozi (Sarakusti).", "1303f83d"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1112-06-28:0":{"b": ["Ali b. Jusuf opsjeo je Toledo (Tulajtulu), ali ga nije uspio zauzeti", "d35d4a4e"], "d": ["Tokom drugog prelaska Alija b. Jusufa u Andaluziju opsjednuta je Tulajtula; zbog snažnog otpora opsada je dignuta (506/1112–13), a zauzvrat su zauzeti Madrid i neka mjesta u okolici.", "106302f2"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1118-12-19:0":{"b": ["Aragonski kralj Alfonso I ušao je u Zaragozu; grad je od Almoravida prešao Aragonu", "49a4a80d"], "d": ["Zaragoza, kojoj su nakon duge opsade ponestale zalihe, prihvatila je 11. decembra 1118. uslove predaje; Alfonso I ušao je u grad 18. decembra. Zaragoza je postala prijestolnica Aragonskog kraljevstva.", "25de2b0c"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1121-11-13:0":{"b": ["Ibn Tumert proglasio se mehdijem", "33dad2aa"], "d": ["Ibn Tumert, protjeran iz almoravidske prijestolnice Marakeša, okupio je pristalice i u ramazanu 515 (novembar 1121) proglasio se mehdijem; u planinama Deren počeo je almohadski pokret.", "67c9ea64"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1127-01-01:0":{"b": ["Aragonski kralj opsjeo je Granadu, ali se povukao", "60877b49"], "d": ["Na poticaj kršćana u Granadi aragonski kralj opsjeo je grad; zbog žestoke odbrane 1127. morao se povući.", "1684bbe7"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1132-01-01:0":{"b": ["Kastiljski kralj Alfonso VII opljačkao je Sevilju", "23664808"], "d": ["Alfonso VII 526 (1132) opljačkao je Sevilju; almoravidski namjesnik grada ubijen je u borbama.", "342ff94a"]},
