"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1143-01-01:0":{"b": ["Umro je Ali b. Jusuf; na prijestolje je stupio njegov sin Tašfin (537, 1143).", "7342e8f8"], "d": ["Umro je Ali b. Jusuf; na prijestolje je stupio njegov sin Tašfin (537, 1143).", "7342e8f8"]},
